import Box, { BoxProps } from "@mui/material/Box";
import { styled } from "@mui/material/styles";
import { appColors } from "../../theme/appColors";

const fbc = styled(Box)<BoxProps>(({ theme }) => ({
  '@media (min-width:431px)': {
    height: '294px',
    display: 'flex',
    flexDirection: 'column',
    position: 'absolute',
    top: 0,
    bottom: 0,
    margin: 'auto',
    right: 0,
    left: 0
  },
  '@media (max-width:430px)': {
    height: '100vh',
    paddingLeft: '29px',
    paddingRight: '29px',
  }
}));

const fbx = styled(Box)<BoxProps>(({ theme }) => ({
  display: 'flex',
  flexDirection: 'column',
  paddingLeft: '17px',
  paddingRight: '17px',
  justifyContent: 'center',
  fontWeight: 325,
  textAlign: 'center',
  alignItems: 'center',
  height: 'calc(100% - 80px)',
  '& h6, img': {
    color: `${appColors.darkGray[100]}`
  }

}));

export {
  fbc as FallbackContainer,
  fbx as FallbackContent,
};
