import * as React from 'react';
import Box, { BoxProps } from '@mui/material/Box';
import { useLocation, useNavigate } from 'react-router-dom';
import { FallbackContainer, FallbackContent } from '../MuiStyled/fallback';
import { useTranslation } from 'react-i18next';
import { FallbackButtonStyle, FallbackSubtitleStyle, FallbackTitleStyle } from '../../theme/fallback';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';

const imageBoxProps = {
  alt: 'Error Boundary',
  height:'84px',
  src:'/images/error-boundary.png'
}

const Fallback = (
  { ...props }:  BoxProps ) => {
  const { state } = useLocation();
  const defaultState = { page: 'dashboard', buttonPath: '/dashboard' }
  const { page, buttonPath } = state || defaultState;
  const navigate = useNavigate();
  const { t } = useTranslation('home');
  const handleButton =() => {
      navigate(buttonPath);
  }
  const pages = page as 'default' | 'dashboard';

  return (
    <FallbackContainer
      data-testid="fallback-container"
      {...props}
    >
      <FallbackContent>
        <Box
          component="img"
          {...imageBoxProps}
        />
        <Typography
          sx={{ ...FallbackTitleStyle }}
          variant='h6'
        >{t(`fallback.${pages}.title`)}</Typography>
        <Typography
          sx={{ ...FallbackSubtitleStyle }}
          variant='subtitle1'
        >{t(`fallback.${pages}.subTitle`)}</Typography>
      </FallbackContent>
      <Button
        fullWidth
        onClick={handleButton}
        sx={{ ...FallbackButtonStyle }}
        variant="outlined"
      >
        <Typography
          sx={{ textTransform: 'uppercase' }}
          variant="body1"
        >
          {t(`fallback.${pages}.return`)}
        </Typography>
      </Button>
    </FallbackContainer>
  )
}

export default Fallback;
